from test_bufftap import test, tests
from test_nearby import setup

test('Full check-up gathers every report into one copy box',"local B=BuffTap; B:Options(); B:ShowReport('checkup'); local t=B.options.discoveryReport.text or B.options.discoveryReport:GetText(); for _,h in ipairs({'Full check-up','== Game ==','== Diagnostics ==','== Debug ==','== Nearby ==','== Supplies ==','== Settings (import string, without your blacklist) =='}) do assert(t:find(h,1,true),h) end; assert(B.options.diagCheckup)")
test('/bt checkup opens the full check-up',"local B=BuffTap; SlashCmdList.BUFFTAP('checkup'); local t=B.options.discoveryReport:GetText(); assert(t:find('== Debug ==',1,true))")
test('Nearby sidebar light turns red when friendly nameplates are off',setup+"local B=BuffTap; B:Options(); B:UpdateNavStatus(); local tab=B.options.tabs[4]; assert(tab.statusOn and not tab.statusWarning); platesEnabled=false; C_CVar.GetCVar=nil; GetCVar=function() return '0' end; B:UpdateNavStatus(); assert(tab.statusWarning and tab.statusWarning:find('Shift+V',1,true))")
HOLD=setup+"local B=BuffTap; IsResting=function() return true end; B.db.nearbyWhileResting=true; "
test('Hold back short buffs skips Thorns on Nearby while resting',HOLD+"aura('nameplate1',5232,'Mark of the Wild'); B.db.nearbyHoldShort=true; B.nearbyNeedCache={}; B.nearbySnapshot=nil; refresh(); assert(#B:NearbyCandidates(true)==0, 'thorns offered'); B.db.nearbyHoldShort=false; B.nearbyNeedCache={}; refresh(); local c=B:NearbyCandidates(true); assert(c[1] and c[1].actions[1].key=='thorns')")
test('Hold back short buffs still offers long buffs',HOLD+"B.db.nearbyHoldShort=true; B.nearbyNeedCache={}; refresh(); local c=B:NearbyCandidates(true); assert(c[1] and c[1].actions[1].key=='motw' and #c[1].actions==1)")
test('Short buffs are only held back while resting',setup+"local B=BuffTap; IsResting=function() return false end; B.db.nearbyWhileResting=true; B.db.nearbyHoldShort=true; aura('nameplate1',5232,'Mark of the Wild'); B.nearbyNeedCache={}; refresh(); local c=B:NearbyCandidates(true); assert(c[1] and c[1].actions[1].key=='thorns')")
test('Nearby page groups buffing left and list look right',"local B=BuffTap; B:Options(); local f=B.options; local p=f.pages[4]; assert(f.nearbyHoldShort and p.openWindow and p.requestsShortcut); assert(f.nearbyHoldShort.text and f.nearbyHoldShort.text:find('Thorns',1,true) or true)")
test('Hold back switch saves and follows Buff while resting',"local B=BuffTap; B:Options(); local f=B.options; f.nearbyHoldShort:SetChecked(true); f.nearbyHoldShort.scripts.OnClick(f.nearbyHoldShort); assert(B.db.nearbyHoldShort==true); B.db.pauseResting=true; B.db.nearbyWhileResting=false; B:UpdateRefinedOptions(); B:Options(); assert(f.nearbyHoldShort.enabled==false or f.nearbyHoldShort:IsEnabled()==false); B.db.nearbyWhileResting=true; B:Options(); assert(f.nearbyHoldShort:IsEnabled()~=false)")
test('Open window button opens the Nearby window',"local B=BuffTap; B:Options(); local called; B.ShowNearbySetup=function() called=true end; local b=B.options.pages[4].openWindow; b.scripts.OnClick(b); assert(called)")
test('Full check-up leaves blacklisted names out',"local B=BuffTap; B.db.blockedPlayers={['Secretname-Realm']=true}; B.db.blockedGuilds={['Hidden Guild']=true}; B:Options(); B:ShowReport('checkup'); local t=B.options.discoveryReport:GetText(); assert(not t:find('Secretname',1,true) and not t:find('Hidden Guild',1,true)); assert(t:find('Blacklist: 1 players, 1 guilds',1,true)); assert(B:ExportSettings():find('Secretname',1,true))")
